import{c as a,Q as i,j as s,m as t}from"./chunks/framework.DVSyX6JR.js";const g=JSON.parse('{"title":"WiFi TCP bridge instellen","description":"","frontmatter":{},"headers":[],"relativePath":"docs/tcp-bridge-nl.md","filePath":"docs/tcp-bridge-nl.md"}'),n={name:"docs/tcp-bridge-nl.md"};function r(d,e,p,l,o,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="wifi-tcp-bridge-instellen" tabindex="-1">WiFi TCP bridge instellen <a class="header-anchor" href="#wifi-tcp-bridge-instellen" aria-label="Permalink to &quot;WiFi TCP bridge instellen&quot;">​</a></h1><p>Deze handleiding is voor een repeater waarop de <code>_bridge_tcp</code> firmware is geflasht. De bridge verbindt twee of meer LoRa-netwerken via een centrale TCP server.</p><h2 id="wat-je-nodig-hebt" tabindex="-1">Wat je nodig hebt <a class="header-anchor" href="#wat-je-nodig-hebt" aria-label="Permalink to &quot;Wat je nodig hebt&quot;">​</a></h2><ul><li>Een ESP32 repeater met WiFi en <code>_bridge_tcp</code> firmware.</li><li>De USB poort van de repeater, bijvoorbeeld <code>/dev/ttyACM0</code>.</li><li><code>meshcli</code> op je computer.</li><li>Een TCP bridge server die bereikbaar is vanaf de repeater.</li></ul><h2 id="_1-start-de-tcp-bridge-server" tabindex="-1">1. Start de TCP bridge server <a class="header-anchor" href="#_1-start-de-tcp-bridge-server" aria-label="Permalink to &quot;1. Start de TCP bridge server&quot;">​</a></h2><p>Start de server op een machine die bereikbaar is vanaf de bridge-repeaters. Dat kan een VPS, Raspberry Pi of lokale computer zijn.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tcp_bridge_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span></span></code></pre></div><p>Voor testen en monitoren kun je de server starten met statusregels en heartbeat-timeout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tcp_bridge_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status-interval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --client-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 90</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-packets</span></span></code></pre></div><p>De TCP bridge firmware stuurt elke 30 seconden een heartbeat naar de server. De server gebruikt normale pakketten en heartbeats om de <code>idle</code> timer van de client bij te werken. Als een node stroom verliest en er geen heartbeat meer binnenkomt voor <code>--client-timeout</code>, verbreekt de server die oude verbinding.</p><p>Gebruik bij lokaal testen het LAN-IP van deze machine als <code>bridge.server</code>. Gebruik bij internetgebruik een publiek IP-adres of domeinnaam.</p><h2 id="_2-verbind-met-de-repeater" tabindex="-1">2. Verbind met de repeater <a class="header-anchor" href="#_2-verbind-met-de-repeater" aria-label="Permalink to &quot;2. Verbind met de repeater&quot;">​</a></h2><p>Een TCP bridge build is een repeater, geen serial companion. Gebruik daarom <code>-r</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meshcli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span></code></pre></div><p>Als je deze fout ziet:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>No response from meshcore node, disconnecting</span></span>
<span class="line"><span>Are you sure your node is a serial companion ?</span></span>
<span class="line"><span>To connect to a repeater, use -r option.</span></span></code></pre></div><p>dan miste je <code>-r</code>. Start opnieuw met:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meshcli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span></code></pre></div><h2 id="_3-stel-wifi-en-tcp-bridge-in" tabindex="-1">3. Stel WiFi en TCP bridge in <a class="header-anchor" href="#_3-stel-wifi-en-tcp-bridge-in" aria-label="Permalink to &quot;3. Stel WiFi en TCP bridge in&quot;">​</a></h2><p>Voer deze commando&#39;s in via <code>meshcli</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set bridge.enabled off</span></span>
<span class="line"><span>set wifi.ssid MijnWiFiNaam</span></span>
<span class="line"><span>set wifi.password MijnWiFiWachtwoord</span></span>
<span class="line"><span>set bridge.server 192.168.1.123</span></span>
<span class="line"><span>set bridge.port 4200</span></span></code></pre></div><p>Gebruik in plaats van <code>192.168.1.123</code> het IP-adres of de hostname van jouw TCP bridge server.</p><p>Voor een server op internet:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set bridge.server mijnserver.example.com</span></span></code></pre></div><h2 id="_4-herstart-na-wifi-wijzigingen" tabindex="-1">4. Herstart na WiFi-wijzigingen <a class="header-anchor" href="#_4-herstart-na-wifi-wijzigingen" aria-label="Permalink to &quot;4. Herstart na WiFi-wijzigingen&quot;">​</a></h2><p>Na <code>set wifi.ssid</code> en <code>set wifi.password</code> moet de repeater opnieuw starten voordat de WiFi-instellingen actief worden.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reboot</span></span></code></pre></div><p>Verbind daarna opnieuw:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">meshcli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span></code></pre></div><p>Zet daarna de bridge aan:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set bridge.enabled on</span></span></code></pre></div><h2 id="_5-controleer-de-instellingen" tabindex="-1">5. Controleer de instellingen <a class="header-anchor" href="#_5-controleer-de-instellingen" aria-label="Permalink to &quot;5. Controleer de instellingen&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get bridge.type</span></span>
<span class="line"><span>get wifi.ssid</span></span>
<span class="line"><span>get bridge.server</span></span>
<span class="line"><span>get bridge.port</span></span>
<span class="line"><span>get bridge.enabled</span></span></code></pre></div><p>Verwachte bridge type:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; tcp</span></span></code></pre></div><p><code>get wifi.password</code> toont niet het echte wachtwoord, maar <code>***</code>.</p><h2 id="_6-meerdere-repeaters-koppelen" tabindex="-1">6. Meerdere repeaters koppelen <a class="header-anchor" href="#_6-meerdere-repeaters-koppelen" aria-label="Permalink to &quot;6. Meerdere repeaters koppelen&quot;">​</a></h2><p>Flash op beide locaties een repeater met <code>_bridge_tcp</code> firmware en configureer ze allebei naar dezelfde TCP server en poort:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set bridge.server mijnserver.example.com</span></span>
<span class="line"><span>set bridge.port 4200</span></span>
<span class="line"><span>set bridge.enabled on</span></span></code></pre></div><p>Pakketten die de ene repeater via LoRa ontvangt, gaan via TCP naar de server en worden door de andere repeater weer in zijn lokale LoRa-netwerk gezet.</p><h2 id="problemen-oplossen" tabindex="-1">Problemen oplossen <a class="header-anchor" href="#problemen-oplossen" aria-label="Permalink to &quot;Problemen oplossen&quot;">​</a></h2><h3 id="permission-denied-op-dev-ttyacm0" tabindex="-1">Permission denied op <code>/dev/ttyACM0</code> <a class="header-anchor" href="#permission-denied-op-dev-ttyacm0" aria-label="Permalink to &quot;Permission denied op \`/dev/ttyACM0\`&quot;">​</a></h3><p>Voeg je gebruiker toe aan de <code>dialout</code> groep:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dialout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $USER</span></span></code></pre></div><p>Log daarna uit en opnieuw in.</p><h3 id="verkeerde-seriele-poort" tabindex="-1">Verkeerde seriele poort <a class="header-anchor" href="#verkeerde-seriele-poort" aria-label="Permalink to &quot;Verkeerde seriele poort&quot;">​</a></h3><p>Controleer welke poort verschijnt nadat je de repeater aansluit:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyACM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyUSB</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span></code></pre></div><p>Gebruik daarna de juiste poort met <code>meshcli -s &lt;poort&gt; -r</code>.</p><h3 id="bridge-komt-niet-online" tabindex="-1">Bridge komt niet online <a class="header-anchor" href="#bridge-komt-niet-online" aria-label="Permalink to &quot;Bridge komt niet online&quot;">​</a></h3><p>Controleer:</p><ul><li>Als de CLI traag of rommelig wordt tijdens configureren, voer <code>set bridge.enabled off</code> uit, reboot, en stel daarna eerst WiFi en server in voordat je de bridge weer aanzet.</li><li>De repeater is herstart na het instellen van WiFi.</li><li><code>get bridge.enabled</code> staat op <code>on</code>.</li><li><code>get bridge.server</code> en <code>get bridge.port</code> kloppen.</li><li>De TCP bridge server draait.</li><li>De server is bereikbaar vanaf hetzelfde WiFi-netwerk of via internet.</li><li>Een firewall laat TCP poort <code>4200</code> door.</li></ul><h3 id="server-blijft-een-node-tonen-nadat-de-stroom-eraf-is" tabindex="-1">Server blijft een node tonen nadat de stroom eraf is <a class="header-anchor" href="#server-blijft-een-node-tonen-nadat-de-stroom-eraf-is" aria-label="Permalink to &quot;Server blijft een node tonen nadat de stroom eraf is&quot;">​</a></h3><p>Gebruik de heartbeat-timeout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tcp_bridge_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status-interval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --client-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 90</span></span></code></pre></div><p>De statusregel toont <code>idle</code>, <code>hb_age</code> en <code>hb</code>. Als <code>idle</code> groter wordt dan <code>--client-timeout</code>, verbreekt de server de oude TCP sessie.</p><p>Voor lokaal testen met maximaal een node per IP kun je ook dit gebruiken:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tcp_bridge_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --replace-same-ip</span></span></code></pre></div><p>Gebruik <code>--replace-same-ip</code> niet als meerdere bridge nodes vanaf hetzelfde publieke IP of achter dezelfde NAT kunnen verbinden.</p><h3 id="tcp-bridge-is-niet-versleuteld" tabindex="-1">TCP bridge is niet versleuteld <a class="header-anchor" href="#tcp-bridge-is-niet-versleuteld" aria-label="Permalink to &quot;TCP bridge is niet versleuteld&quot;">​</a></h3><p>De huidige TCP bridge verstuurt verkeer zonder TLS. Gebruik dit op een vertrouwd netwerk of beperk toegang tot de server met firewallregels.</p>`,61)])])}const k=a(n,[["render",r]]);export{g as __pageData,k as default};
